66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    private final OwnerFieldsValidator ownerFieldsValidator;
80	
81	    private final RegistrationDateAssigner registrationDateAssigner;
82	
83	    private final CustomerCodeAssigner customerCodeAssigner;
84	
85	    private final HouseholdDuplicateChecker householdDuplicateChecker;
86	
87	    private final IdentityDuplicateChecker identityDuplicateChecker;
88	
89	    private final HouseholdAssigner householdAssigner;
90	
91	    private final HouseholdSizeAssigner householdSizeAssigner;
92	
93	    private final NamesakeCounter namesakeCounter;
94	
95	    private final MembershipLevelAssigner membershipLevelAssigner;
96	
97	    private final CityCapacityChecker cityCapacityChecker;
98	
99	    private final DailyRegistrationLimiter dailyRegistrationLimiter;
100	
101	    private final BulkSignupWarningAssigner bulkSignupWarningAssigner;
102	
103	    private final OwnerCreationAuditLogger ownerCreationAuditLogger;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper,
109	                                 OwnerFieldsValidator ownerFieldsValidator,
110	                                 RegistrationDateAssigner registrationDateAssigner,
111	                                 CustomerCodeAssigner customerCodeAssigner,
112	                                 HouseholdDuplicateChecker householdDuplicateChecker,
113	                                 IdentityDuplicateChecker identityDuplicateChecker,
114	                                 HouseholdAssigner householdAssigner,
115	                                 HouseholdSizeAssigner householdSizeAssigner,
116	                                 NamesakeCounter namesakeCounter,
117	                                 MembershipLevelAssigner membershipLevelAssigner,
118	                                 CityCapacityChecker cityCapacityChecker,
119	                                 DailyRegistrationLimiter dailyRegistrationLimiter,
120	                                 BulkSignupWarningAssigner bulkSignupWarningAssigner,
121	                                 OwnerCreationAuditLogger ownerCreationAuditLogger) {
122	        this.clinicService = clinicService;
123	        this.ownerMapper = ownerMapper;
124	        this.petMapper = petMapper;
125	        this.visitMapper = visitMapper;
126	        this.ownerFieldsValidator = ownerFieldsValidator;
127	        this.registrationDateAssigner = registrationDateAssigner;
128	        this.customerCodeAssigner = customerCodeAssigner;
129	        this.householdDuplicateChecker = householdDuplicateChecker;
130	        this.identityDuplicateChecker = identityDuplicateChecker;
131	        this.householdAssigner = householdAssigner;
132	        this.householdSizeAssigner = householdSizeAssigner;
133	        this.namesakeCounter = namesakeCounter;
134	        this.membershipLevelAssigner = membershipLevelAssigner;
135	        this.cityCapacityChecker = cityCapacityChecker;
136	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
137	        this.bulkSignupWarningAssigner = bulkSignupWarningAssigner;
138	        this.ownerCreationAuditLogger = ownerCreationAuditLogger;
139	    }
140	
141	    @InitBinder("ownerFieldsDto")
142	    void initOwnerFieldsBinder(WebDataBinder binder) {
143	        binder.addValidators(ownerFieldsValidator);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
149	        Collection<Owner> owners;
150	        if (lastName != null) {
151	            owners = this.clinicService.findOwnerByLastName(lastName);
152	        } else {
153	            owners = this.clinicService.findAllOwners();
154	        }
155	        if (owners.isEmpty()) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
174	        HttpHeaders headers = new HttpHeaders();
175	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
176	        this.registrationDateAssigner.assign(owner);
177	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
178	            return new ResponseEntity<>(HttpStatus.CONFLICT);
179	        }
180	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
181	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
182	        }
183	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
184	        if (sharesHousehold && this.householdDuplicateChecker.isDuplicate(owner)) {
185	            this.householdAssigner.assign(owner);
186	        }
187	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        this.householdSizeAssigner.assign(owner);
191	        this.customerCodeAssigner.assign(owner);
192	        this.namesakeCounter.assign(owner);
193	        this.membershipLevelAssigner.assign(owner);
194	        this.bulkSignupWarningAssigner.assign(owner);
195	        this.clinicService.saveOwner(owner);
196	        this.ownerCreationAuditLogger.logCreated(owner);
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        currentOwner.setAddress(ownerFieldsDto.getAddress());
211	        currentOwner.setCity(ownerFieldsDto.getCity());
212	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
213	        currentOwner.setLastName(ownerFieldsDto.getLastName());
214	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
215	        currentOwner.setEmail(ownerFieldsDto.getEmail());
216	        this.clinicService.saveOwner(currentOwner);
217	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Transactional
222	    @Override
223	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        this.clinicService.deleteOwner(owner);
229	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        HttpHeaders headers = new HttpHeaders();
240	        Pet pet = petMapper.toPet(petFieldsDto);
241	        owner.setId(ownerId);
242	        pet.setOwner(owner);
243	        pet.getType().setName(null);
244	        this.clinicService.savePet(pet);
245	        PetDto petDto = petMapper.toPetDto(pet);
246	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
247	            .buildAndExpand(pet.getId()).toUri());
248	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
254	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
255	        if (currentOwner != null) {
256	            Pet currentPet = this.clinicService.findPetById(petId);
257	            if (currentPet != null) {
258	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
259	                currentPet.setName(petFieldsDto.getName());
260	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
261	                this.clinicService.savePet(currentPet);
262	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
271	        HttpHeaders headers = new HttpHeaders();
272	        Visit visit = visitMapper.toVisit(visitFieldsDto);
273	        Pet pet = new Pet();
274	        pet.setId(petId);
275	        visit.setPet(pet);
276	        this.clinicService.saveVisit(visit);
277	        VisitDto visitDto = visitMapper.toVisitDto(visit);
278	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
279	            .buildAndExpand(visit.getId()).toUri());
280	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
281	    }
282	
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
287	        Owner owner = this.clinicService.findOwnerById(ownerId);
288	        if (owner != null) {
289	            Pet pet = owner.getPet(petId);
290	            if (pet != null) {
291	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
292	            }
293	        }
294	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	    }
296	}
