17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	import org.springframework.validation.Errors;
22	import org.springframework.validation.ValidationUtils;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Validates an {@link OwnerFieldsDto} as part of the {@code @Valid} pass on the owner
27	 * request body: the address is canonicalised and then, like the other required text fields,
28	 * required to be present and non-blank; the telephone is canonicalised to E.164 form and
29	 * required to be a valid such number; an optional email is required to be syntactically
30	 * valid and normalized to lower case; and an optional postcode, when present, is required to
31	 * be a 4-digit code valid for the owner's city.
32	 * <p>
33	 * Registered on the owner controller through {@code @InitBinder} so every rejected field is
34	 * recorded as a field error on the shared {@link Errors}, surfacing through the usual
35	 * bad-request handling. The canonical address and a valid telephone (in E.164 form) are
36	 * written back to the DTO so they are stored, returned and compared for duplicates as those
37	 * canonical strings.
38	 *
39	 * @author Vitaliy Fedoriv
40	 */
41	@Component
42	public class OwnerFieldsValidator implements Validator {
43	
44	    private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "address", "city", "telephone"};
45	
46	    private final TelephoneNormalizer telephoneNormalizer;
47	
48	    private final EmailNormalizer emailNormalizer;
49	
50	    private final AddressNormalizer addressNormalizer;
51	
52	    private final PostcodeValidator postcodeValidator;
53	
54	    public OwnerFieldsValidator(TelephoneNormalizer telephoneNormalizer, EmailNormalizer emailNormalizer,
55	                                AddressNormalizer addressNormalizer, PostcodeValidator postcodeValidator) {
56	        this.telephoneNormalizer = telephoneNormalizer;
57	        this.emailNormalizer = emailNormalizer;
58	        this.addressNormalizer = addressNormalizer;
59	        this.postcodeValidator = postcodeValidator;
60	    }
61	
62	    @Override
63	    public boolean supports(Class<?> clazz) {
64	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
65	    }
66	
67	    @Override
68	    public void validate(Object target, Errors errors) {
69	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
70	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
71	        for (String field : REQUIRED_FIELDS) {
72	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
73	        }
74	        if (!errors.hasFieldErrors("telephone")) {
75	            normalizeTelephone(owner, errors);
76	        }
77	        normalizeEmail(owner, errors);
78	        validatePostcode(owner, errors);
79	    }
80	
81	    private void validatePostcode(OwnerFieldsDto owner, Errors errors) {
82	        String postcode = owner.getPostcode();
83	        if (postcode == null) {
84	            return;
85	        }
86	        if (!postcodeValidator.isValid(owner.getCity(), postcode)) {
87	            errors.rejectValue("postcode", "postcode.invalid",
88	                "must be a valid postcode for the city");
89	        }
90	    }
91	
92	    private void normalizeTelephone(OwnerFieldsDto owner, Errors errors) {
93	        telephoneNormalizer.toE164(owner.getTelephone()).ifPresentOrElse(
94	            owner::setTelephone,
95	            () -> errors.rejectValue("telephone", "telephone.invalid",
96	                "must be a valid telephone number in E.164 form"));
97	    }
98	
99	    private void normalizeEmail(OwnerFieldsDto owner, Errors errors) {
100	        String email = owner.getEmail();
101	        if (email == null) {
102	            return;
103	        }
104	        if (emailNormalizer.isValid(email)) {
105	            owner.setEmail(emailNormalizer.normalize(email));
106	        } else {
107	            errors.rejectValue("email", "email.invalid", "must be a valid email address");
108	        }
109	    }
110	}
