27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "membership_level")
73	    private Integer membershipLevel;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    /**
138	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
139	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
140	     * {@code "SYD-SMI-0007-M26"}. Derived from the owner's own fields; {@code null} until
141	     * both the customer code and registration date have been assigned.
142	     */
143	    @Transient
144	    public String getMembershipNumber() {
145	        if (this.customerCode == null || this.registrationDate == null) {
146	            return null;
147	        }
148	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
149	    }
150	
