17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.samples.petclinic.service.ClinicService;
28	import org.springframework.stereotype.Component;
29	
30	/**
31	 * Groups owners into households and derives a household's stable shared identifier.
32	 * <p>
33	 * Two owners belong to the same household when they carry the same last name and the same
34	 * address. The last name is compared leniently: surrounding whitespace is trimmed, internal
35	 * runs of whitespace are collapsed to a single space and letters are compared without
36	 * regard to case, so values that differ only in spacing or capitalisation are treated as
37	 * equal. The address is compared in its canonical {@link AddressNormalizer normalized} form,
38	 * the same form under which it is stored and returned.
39	 */
40	@Component
41	public class HouseholdMatcher {
42	
43	    /** Runs of whitespace collapsed to a single space before comparison. */
44	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
45	
46	    private final ClinicService clinicService;
47	
48	    private final AddressNormalizer addressNormalizer;
49	
50	    public HouseholdMatcher(ClinicService clinicService, AddressNormalizer addressNormalizer) {
51	        this.clinicService = clinicService;
52	        this.addressNormalizer = addressNormalizer;
53	    }
54	
55	    /**
56	     * Returns the already-stored owners that share {@code candidate}'s household under the
57	     * lenient comparison described above. The candidate itself is not yet stored, so it is
58	     * never included.
59	     *
60	     * @param candidate the owner being created
61	     * @return existing household members, possibly empty
62	     */
63	    public List<Owner> findMembers(Owner candidate) {
64	        String key = householdKey(candidate);
65	        return clinicService.findAllOwners().stream()
66	            .filter(existing -> householdKey(existing).equals(key))
67	            .toList();
68	    }
69	
70	    /**
71	     * The stable identifier for {@code candidate}'s household, derived deterministically
72	     * from its (normalised) last name and address so that every member resolves to the
73	     * same value.
74	     *
75	     * @param candidate an owner in the household
76	     * @return a non-blank household identifier
77	     */
78	    public String householdId(Owner candidate) {
79	        byte[] digest = sha256(householdKey(candidate));
80	        StringBuilder sb = new StringBuilder(12);
81	        for (int i = 0; i < 6; i++) {
82	            sb.append(String.format("%02X", digest[i]));
83	        }
84	        return sb.toString();
85	    }
86	
87	    private String householdKey(Owner owner) {
88	        return normalizeName(owner.getLastName()) + "\n" + addressNormalizer.normalize(owner.getAddress());
89	    }
90	
91	    private String normalizeName(String value) {
92	        if (value == null) {
93	            return "";
94	        }
95	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
96	    }
97	
98	    private byte[] sha256(String value) {
99	        try {
100	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
101	        }
102	        catch (NoSuchAlgorithmException ex) {
103	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
104	        }
105	    }
106	}
