34	    private final ClinicService clinicService;
35	
36	    public IdentityDuplicateChecker(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * Reports whether an already-stored owner shares {@code candidate}'s identity key.
42	     *
43	     * @param candidate the owner being created, not yet stored
44	     * @return {@code true} when another owner already carries the same identity key
45	     */
46	    public boolean isDuplicate(Owner candidate) {
47	        String identityKey = candidate.getIdentityKey();
48	        return clinicService.findAllOwners().stream()
49	            .anyMatch(existing -> existing.getIdentityKey().equals(identityKey));
