27	/**
28	 * Canonicalises an owner postal address.
29	 * <p>
30	 * Surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a single
31	 * space and letters are upper-cased, so addresses that differ only in spacing or
32	 * capitalisation share a single canonical form. Common street-type abbreviations are then
33	 * expanded token by token ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
34	 * {@code AVE}->{@code AVENUE}) so those variants canonicalise identically too. A blank input
35	 * canonicalises to the empty string.
36	 */
37	@Component
38	public class AddressNormalizer {
39	
40	    /** Runs of whitespace collapsed to a single space. */
41	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
42	
43	    /** Street-type abbreviations expanded to their full (upper-cased) form. */
44	    private static final Map<String, String> ABBREVIATIONS = Map.of(
45	        "ST", "STREET",
46	        "RD", "ROAD",
47	        "AVE", "AVENUE");
48	
49	    /**
50	     * Converts a raw address into its canonical form.
51	     *
52	     * @param raw the address as supplied by the client, possibly {@code null}
53	     * @return the canonical address, or the empty string when {@code raw} is {@code null} or
