25	/**
26	 * Validates an owner postcode against the owner's city.
27	 * <p>
28	 * A postcode is valid when it is a 4-digit code that is acceptable for the region derived
29	 * from the city via the fixed {@link CityRegionTable}: within that region's range per the
30	 * fixed {@link RegionPostcodeTable}, or any 4-digit value when the city has no known region.
31	 */
32	@Component
33	public class PostcodeValidator {
34	
35	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
36	
37	    /**
38	     * @param city     the owner's city, used to resolve the region whose range applies
39	     * @param postcode a postcode as supplied by the client
40	     * @return {@code true} when {@code postcode} is a 4-digit code valid for the city
41	     */
42	    public boolean isValid(String city, String postcode) {
43	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
44	            return false;
45	        }
46	        return RegionPostcodeTable.accepts(CityRegionTable.regionOf(city), Integer.parseInt(postcode));
47	    }
48	}
