45	@Repository
46	@Profile("jpa")
47	public class JpaOwnerRepositoryImpl implements OwnerRepository {
48	
49	    @PersistenceContext
50	    private EntityManager em;
51	
52	
53	    /**
54	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
55	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
56	     * There are some ways to improve it such as:
57	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
58	     * - Turning on lazy-loading and using open session in view pattern
59	     */
60	    @SuppressWarnings("unchecked")
61	    public Collection<Owner> findByLastName(String lastName) {
62	        // using 'join fetch' because a single query should load both owners and pets
63	        // using 'left join fetch' because it might happen that an owner does not have pets yet
64	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
65	        query.setParameter("lastName", lastName + "%");
66	        return query.getResultList();
67	    }
68	
69	    @Override
70	    @SuppressWarnings("unchecked")
71	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
72	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
73	        query.setParameter("lastName", lastName + "%");
74	        query.setFirstResult((int) pageable.getOffset());
75	        query.setMaxResults(pageable.getPageSize());
76	        List<Owner> owners = query.getResultList();
77	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
78	        countQuery.setParameter("lastName", lastName + "%");
79	        long total = (long) countQuery.getSingleResult();
80	        return new PageImpl<>(owners, pageable, total);
81	    }
82	
83	    @Override
84	    public Owner findById(int id) {
85	        // using 'join fetch' because a single query should load both owners and pets
86	        // using 'left join fetch' because it might happen that an owner does not have pets yet
87	        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
88	        query.setParameter("id", id);
89	        return (Owner) query.getSingleResult();
90	    }
91	
92	
93	    @Override
94	    public boolean existsByTelephone(String telephone) throws DataAccessException {
95	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.telephone = :telephone");
96	        query.setParameter("telephone", telephone);
97	        return (long) query.getSingleResult() > 0;
98	    }
99	
100	    @Override
101	    public boolean existsByEmailIgnoreCase(String email) throws DataAccessException {
102	        Query query = this.em.createQuery(
103	            "SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.email) = LOWER(:email)");
104	        query.setParameter("email", email);
105	        return (long) query.getSingleResult() > 0;
106	    }
107	
108	    @Override
109	    public long count() throws DataAccessException {
110	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
111	        return (long) query.getSingleResult();
112	    }
113	
114	    @Override
115	    public long countByCity(String city) throws DataAccessException {
116	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.city = :city");
117	        query.setParameter("city", city);
118	        return (long) query.getSingleResult();
119	    }
120	
121	    @Override
122	    public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
123	        Query query = this.em.createQuery(
124	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
125	        query.setParameter("registrationDate", registrationDate);
126	        return (long) query.getSingleResult();
127	    }
128	
129	    @Override
130	    public void save(Owner owner) {
131	        if (owner.getId() == null) {
132	            this.em.persist(owner);
133	        } else {
134	            this.em.merge(owner);
135	        }
136	
137	    }
138	
139		@SuppressWarnings("unchecked")
140		@Override
141		public Collection<Owner> findAll() throws DataAccessException {
142			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
143	        return query.getResultList();
144		}
145	
146	    @SuppressWarnings("unchecked")
147	    @Override
148	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
149	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
150	        query.setFirstResult((int) pageable.getOffset());
151	        query.setMaxResults(pageable.getPageSize());
152	        List<Owner> owners = query.getResultList();
153	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
154	        long total = (long) countQuery.getSingleResult();
155	        return new PageImpl<>(owners, pageable, total);
156	    }
157	
158		@Override
159		public void delete(Owner owner) throws DataAccessException {
160			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
161		}
